#if canImport(SwiftUI)
import SwiftUI
import KnowledgeOSCoreBridge
struct DocumentReaderView:View { @ObservedObject var viewModel:DocumentReaderViewModel; let documentID:String; var body:some View { VStack(spacing:0){ HStack{ Menu("Contents"){ForEach(viewModel.descriptor?.sections ?? []){s in Button(s.title){Task{await viewModel.goToSection(s)}}}}; Spacer(); Button{Task{await viewModel.previousPage()}}label:{Image(systemName:"chevron.left")}.disabled(!viewModel.canGoBackward); Text("Page \(viewModel.page?.pageNumber ?? 0) of \(viewModel.page?.pageCount ?? 0)").monospacedDigit(); Button{Task{await viewModel.nextPage()}}label:{Image(systemName:"chevron.right")}.disabled(!viewModel.canGoForward); Spacer(); Button{viewModel.zoom=max(0.75,viewModel.zoom-0.1)}label:{Image(systemName:"textformat.size.smaller")}; Button{viewModel.zoom=min(2,viewModel.zoom+0.1)}label:{Image(systemName:"textformat.size.larger")}; ProgressView(value:viewModel.progress).frame(width:100)}.padding(); Divider(); if viewModel.isLoading && viewModel.page==nil{ProgressView("Opening Document…").frame(maxWidth:.infinity,maxHeight:.infinity)} else if let m=viewModel.errorMessage{ContentUnavailableView("Document could not be opened",systemImage:"exclamationmark.triangle",description:Text(m))} else if let p=viewModel.page{ScrollView{VStack(alignment:.leading,spacing:24){Text(viewModel.descriptor?.title ?? "").font(.largeTitle.bold()); Text(p.content).font(.system(size:17*viewModel.zoom,design:.serif)).textSelection(.enabled).frame(maxWidth:760,alignment:.leading)}.padding(48).frame(maxWidth:.infinity)}} else {ContentUnavailableView("No Document",systemImage:"doc.text")}}.task(id:documentID){await viewModel.open(id:documentID)} } }
#endif
